flowchart TD
  start["Início: Analisar 'COMO'"] --> dec_causal{"Está no início absoluto da frase com sentido de motivo?"}
  dec_causal -- "Sim" --> res_causal["Causal<br/>(Equivale a 'já que')"]
  dec_causal -- "Não" --> dec_comparativo{"Introduz analogia ou comparação entre dois termos?"}
  dec_comparativo -- "Sim" --> res_comparativo["Comparativo<br/>(Equivale a 'tal qual')"]
  dec_comparativo -- "Não" --> dec_conformativo{"Substituível por 'conforme' ou 'segundo'?"}
  dec_conformativo -- "Sim" --> res_conformativo["Conformativo<br/>(Ideia de conformidade/acordo)"]
  dec_conformativo -- "Não" --> dec_aditivo{"Vem após 'não só' ou 'não apenas'?"}
  dec_aditivo -- "Sim" --> res_aditivo["Aditivo<br/>(Equivale a 'mas também')"]
  dec_aditivo -- "Não" --> res_outros["Outras Funções<br/>(Pronome relativo, advérbio ou verbo)"]
